from pathlib import Path
import re

p = Path('system-build-current.html')
s = p.read_text()

def once(old, new, label):
    global s
    n = s.count(old)
    if n != 1:
        raise SystemExit(f'{label}: expected one match, found {n}')
    s = s.replace(old, new, 1)

start = s.index('<section class="page" id="alcove-config">')
end = s.index('<section class="page" id="alcove-review">', start)
new_config = '''<section class="page" id="alcove-config"><div style="min-width:0;border-right:1px solid var(--border)"><div style="padding:24px 24px 8px"><h1 style="font-size:23px;margin:0">Make it yours</h1><p class="sub" style="margin:4px 0 0">The room is the reference. The unit is what User 1 defined inside it.</p></div><div class="cfg" style="padding:0 24px 8px"><div style="min-width:0"><svg id="alcove-draw" viewBox="0 0 300 210" style="width:100%;display:block;background:#f2ece2;border-radius:9px"></svg><div class="call" style="margin:10px 0 0"><p style="font-weight:600;margin-bottom:8px">How User 1 defined the starting version</p><p class="dim"><b style="color:var(--text)">1 · Start with the room.</b> The ceiling is 94½ in. That is captured context, not the height of the shelving.</p><p class="dim"><b style="color:var(--text)">2 · Set the unit height.</b> She chose 72 in so the shelving fits the scale of the room and leaves 22½ in above it. The 65 in shelf remains a shelf position, not the top of the unit.</p><p class="dim"><b style="color:var(--text)">3 · Fit the opening.</b> The opening measures 45½ in and she chose the full 45½ in for the unit. She would rather trim a little drywall at installation than build a deliberate gap into the furniture.</p><p class="dim"><b style="color:var(--text)">4 · Keep it behind the face.</b> The available depth is 14½ in. She chose 14 in so the shelf fronts stay ½ in back instead of sticking out.</p><p class="dim"><b style="color:var(--text)">5 · Place the shelves on purpose.</b> Five shelves. One lands at 45 in to line up with the mantel. The 65 in shelf is where she wanted it by eye; the others remain editable.</p><p class="dim"><b style="color:var(--text)">6 · Pick the material.</b> Pine is the starting preference shown here. Changing material changes the reference material and price basis without changing her geometry.</p><p class="dim" style="margin:0"><b style="color:var(--text)">Resolution.</b> Controlling dimensions are carried to the nearest 1/32 in. The scan remains supporting context.</p></div></div><div class="ctl"><div class="control"><label><span>Room height</span><span>94½ in · captured</span></label><p class="dim" style="margin:2px 0 0;font-size:10.5px">Floor to ceiling reference from capture.</p></div><div class="control"><label><span>Unit height</span><span id="v-h">72 in</span></label><input id="c-h" type="range" min="48" max="72" step="0.03125" value="72"></div><div class="control"><label><span>Unit width</span><span id="v-w">45½ in · opening 45½</span></label><input id="c-w" type="range" min="42" max="45.5" step="0.03125" value="45.5"></div><div class="control"><label><span>Depth</span><span id="v-d">14 in · from 14½ measured</span></label><input id="c-d" type="range" min="8" max="16" step="0.03125" value="14"></div><div class="control"><label><span>Shelves</span><span id="v-n">5 shelves</span></label><input id="c-n" type="range" min="2" max="7" value="5"></div><div style="display:flex;justify-content:space-between;align-items:baseline;margin:8px 0 4px"><span style="font-weight:600">Shelf heights</span><button id="fmt" style="font-size:10px;padding:2px 7px">fractions</button></div><div id="shelves" style="margin-bottom:10px"></div><p style="margin:0 0 6px;font-weight:600">Material</p><div id="species" class="swatches"><button class="swatch on" data-material="pine"><span class="dot" style="background:#C9A227"></span>Pine</button><button class="swatch" data-material="poplar"><span class="dot" style="background:#9FA678"></span>Poplar</button><button class="swatch" data-material="cherry"><span class="dot" style="background:#A6522C"></span>Cherry</button><button class="swatch" data-material="oak"><span class="dot" style="background:#C4A06A"></span>Oak</button></div></div></div><div class="calcbox"><p class="calchd">RESULTING DEFINITION / REFERENCE ORDER — USER 1</p><div class="cols"><div><div class="kv"><span>Room reference</span><span>94½ in ceiling</span></div><div class="kv"><span>Unit height</span><span id="p-h">72 in</span></div><div class="kv"><span>Unit width</span><span id="p-w">45½ in</span></div><div class="kv"><span>Unit depth</span><span id="p-d">14 in</span></div><div class="kv"><span>Interior span</span><span id="p-span">44 in</span></div><div class="kv"><span>Fit approach</span><span id="p-fit">full-width fit</span></div></div><div><div class="kv"><span>Shelves</span><span id="p-shelves">5</span></div><div class="kv"><span>Shelf heights</span><span id="p-heights"></span></div><div class="kv"><span>Material</span><span id="p-material">Pine</span></div><div class="kv"><span>Back</span><span>none</span></div><div class="kv"><span>Resolution</span><span>nearest 1/32 in</span></div></div></div><div style="border-top:1px solid var(--border-accent);padding-top:12px;margin-top:12px"><p class="calchd">MATERIAL REQUIRED</p><p style="margin:0 0 10px" id="p-mat"></p><div class="pricebar"><div><p class="calchd">REFERENCE CALCULATED PRICE</p><p style="margin:2px 0 0;font-size:11.5px;color:var(--text2)" id="p-basis"></p></div><p class="pricebig" id="p-price">$0</p></div><p id="p-cfg" class="dim" style="margin:10px 0 0"></p><p class="dim" style="margin:5px 0 0">This block is generated from the choices above and changes with them. It is a definition and reference price basis, not a submitted order.</p></div></div><div class="how"><p style="font-weight:600;margin:0 0 8px">STORE / PRICE BASIS</p><div style="border-top:1px solid var(--border);padding:12px 0 0"><div class="cols"><div><p style="margin:0 0 7px;font-weight:600">Store Zero reference model</p><div class="kv"><span>Shelf SKU</span><span id="o-sku"></span></div><div class="kv"><span>Unit price</span><span id="o-unit"></span></div><div class="kv"><span>Reference on hand</span><span id="o-oh"></span></div><div class="kv"><span>Nominal interior span</span><span id="o-span">44 in</span></div><div class="kv"><span>Ordered cut length</span><span>not set on this page</span></div><div class="kv"><span>Pieces across</span><span id="o-across"></span></div><div class="kv"><span>96 in boards</span><span id="o-b96"></span></div><div class="kv"><span>72 in side members</span><span>4</span></div><div class="kv"><span>Material</span><span id="o-mat"></span></div><div class="kv"><span>Hardware pack</span><span id="o-hw"></span></div></div><div><p style="margin:0 0 7px;font-weight:600">Cell D-001 reference economics</p><div class="kv"><span>Cycle model</span><span>S2-0.1</span></div><div class="kv"><span>Basis</span><span>CALCULATED</span></div><div class="kv"><span>Measured</span><span style="color:#b8860b">false</span></div><div class="kv"><span>Job time</span><span id="o-cyc"></span></div><div class="kv"><span>Cell recovery</span><span id="o-rec"></span></div><p style="margin:10px 0 7px;font-weight:600">Pricing engine</p><div class="kv"><span>Engine</span><span>STB-STORE-ZERO-PRICE-1</span></div><div class="kv"><span>Version</span><span>0.2.2</span></div><div class="kv"><span>Catalog clock</span><span>2026-09-10</span></div><div class="kv"><span>Mark-on</span><span>5%</span></div></div></div><p style="margin:12px 0 0;color:var(--text2)">The interior span is the configured unit width less two ¾ in class side members. User 1's starting version uses the full 45½ in opening, so the starting nominal interior span is 44 in and no hidden fit allowance is subtracted.</p><p style="margin:8px 0 0;color:var(--text2)"><b>REFERENCE ECONOMICS:</b> the displayed amount uses the recovered Store Zero 0.2.2 budgetary model. A dimension can change without changing the price when the same stock count still covers the definition.</p></div></div><div style="padding:14px 24px 20px"><div class="btns"><button data-go="store">REVIEW AND CONFIRM</button></div></div></div><aside class="rail"><p class="hd">BUILD GUIDE</p><p class="goal">Goal</p><div class="row"><b>Room ≠ unit</b><span>Capture establishes context. User 1 sets the furniture.</span></div><div class="row"><b>Show her decisions</b><span>Height, width, depth, shelves and material stay visible beside the tool.</span></div><div class="row"><b>Generate the result</b><span>Definition, material and reference price stay on the page together.</span></div><div class="row"><b>Do not hide the basis</b><span>The human reason and Store math are both visible.</span></div></aside></section>

'''
s = s[:start] + new_config + s[end:]

once('<div class="kv"><span>Opening width</span><span>45½ in — controlling</span></div><div class="kv"><span>Side thickness</span><span>¾ in each — bounded class</span></div><div class="kv"><span>Nominal interior span</span><span>44 in — derived before ordering decision</span></div><div class="kv"><span>Ordered-size adjustment</span><span>not decided on this page</span></div><div class="kv"><span>Shelves</span><span id="r-n">5</span></div>', '<div class="kv"><span>Room height</span><span>94½ in — captured reference</span></div><div class="kv"><span>Opening width</span><span>45½ in — measured reference</span></div><div class="kv"><span>Unit height</span><span id="r-uh">72 in</span></div><div class="kv"><span>Unit width</span><span id="r-uw">45½ in</span></div><div class="kv"><span>Side thickness</span><span>¾ in each — bounded class</span></div><div class="kv"><span>Nominal interior span</span><span id="r-span">44 in</span></div><div class="kv"><span>Fit allowance / ordered-size reduction</span><span id="r-fit">0 in — full-width fit</span></div><div class="kv"><span>Shelves</span><span id="r-n">5</span></div>', 'review geometry block')
once('<p class="dim" style="margin-bottom:18px">The ordered-size adjustment has not been recorded yet. Structural adequacy is not evaluated here.</p>', '<p class="dim" style="margin-bottom:18px">User 1 chose no built-in gap allowance. If local drywall makes the full-width fit tight, her stated field preference is to trim drywall rather than make the unit visibly narrow. Structural adequacy and installation execution are not evaluated here.</p>', 'review unresolved copy')
once('<div class="hdr"><div><b>OPENING</b><span>45½ in</span></div><div><b>SPAN</b><span>44 in nominal</span></div><div><b>SHELVES</b><span id="review-shelves">5</span></div>', '<div class="hdr"><div><b>OPENING</b><span>45½ in measured</span></div><div><b>UNIT</b><span id="review-unit">72 H × 45½ W</span></div><div><b>SPAN</b><span id="review-span">44 in nominal</span></div><div><b>SHELVES</b><span id="review-shelves">5</span></div>', 'review transaction header')
once('<div class="band warn"><b>Current Alcove truth:</b> 44″ nominal interior span; no ordered-size reduction applied. Ordered-size adjustment, structure, installation, commercial terms and allocation remain unresolved.</div>', '<div class="band warn"><b>Current Alcove truth:</b> User 1\'s starting definition is 72″ high × 45½″ wide × 14″ deep with a 44″ nominal interior span and no built-in gap allowance. Structure, installation execution, commercial terms and allocation remain unresolved.</div>', 'terms truth')

once("const alcove={material:'pine',fraction:true,H:[12,24,36,45,65,78,88]};", "const alcove={material:'pine',fraction:true,H:[12,24,36,45,65,68,70]};", 'alcove defaults')

draw_start = s.index('function drawAlcove(')
draw_end = s.index('\nfunction syncAlcove()', draw_start)
new_draw = '''function drawAlcove(n,h,w,d,col,across){const px=1.74,fl=190,ce=fl-94.5*px,x0=118,roomX1=x0+45.5*px,x1=x0+w*px,mt=fl-45*px,sl=6,top=fl-h*px;let s='<rect width="300" height="210" fill="#f2ece2"/><rect y="'+ce+'" width="300" height="'+(fl-ce)+'" fill="#f7f2e9"/>';s+='<rect y="'+fl+'" width="300" height="20" fill="#d9c7a8"/><line x1="0" y1="'+ce+'" x2="300" y2="'+ce+'" stroke="#c9bca8"/>';s+='<rect x="30" y="'+(mt+sl)+'" width="80" height="'+(fl-mt-sl)+'" fill="#e6ddd0"/><rect x="41" y="'+(mt+sl+8)+'" width="58" height="'+(fl-mt-sl-8)+'" fill="#dbd0c0"/><rect x="54" y="'+(fl-42)+'" width="34" height="36" fill="#241d17"/><rect x="24" y="'+mt+'" width="92" height="'+sl+'" fill="#b0824a"/><rect x="24" y="'+mt+'" width="92" height="2" fill="#c99a5e"/>';s+='<line x1="'+x0+'" y1="'+ce+'" x2="'+x0+'" y2="'+fl+'" stroke="#2f6f9e" stroke-width="1" stroke-dasharray="3 3"/><line x1="'+roomX1+'" y1="'+ce+'" x2="'+roomX1+'" y2="'+fl+'" stroke="#2f6f9e" stroke-width="1" stroke-dasharray="3 3"/><line x1="116" y1="'+mt+'" x2="'+roomX1+'" y2="'+mt+'" stroke="#b0824a" stroke-dasharray="4 4"/><text x="'+(roomX1+4)+'" y="'+(mt-3)+'" font-size="8.5" fill="#b0824a" font-family="ui-sans-serif,sans-serif">mantel 45</text>';s+='<rect x="'+x0+'" y="'+top+'" width="'+(x1-x0)+'" height="'+(fl-top)+'" fill="'+col+'" opacity=".16"/><rect x="'+x0+'" y="'+top+'" width="3.5" height="'+(fl-top)+'" fill="'+col+'"/><rect x="'+(x1-3.5)+'" y="'+top+'" width="3.5" height="'+(fl-top)+'" fill="'+col+'"/>';const hs=alcove.H.slice(0,n).slice().sort((a,b)=>a-b);hs.forEach(sh=>{const y=fl-sh*px;s+='<rect x="'+x0+'" y="'+y+'" width="'+(x1-x0)+'" height="'+(0.75*px)+'" fill="'+col+'"/><text x="'+(roomX1+5)+'" y="'+(y+3)+'" font-size="8" fill="#8f8371" font-family="ui-sans-serif,sans-serif">'+fmt(sh)+'</text>'});s+='<text x="'+((x0+roomX1)/2)+'" y="'+(ce+11)+'" font-size="9" fill="#2f6f9e" text-anchor="middle" font-family="ui-sans-serif,sans-serif">room 45½ W · 94½ H</text><text x="'+((x0+x1)/2)+'" y="'+(top-4)+'" font-size="9" fill="'+col+'" text-anchor="middle" font-family="ui-sans-serif,sans-serif">unit '+fmt(w)+' W · '+fmt(h)+' H</text><text x="'+((x0+x1)/2)+'" y="'+(fl+14)+'" font-size="9.5" fill="#8f8371" text-anchor="middle" font-family="ui-sans-serif,sans-serif">'+fmt(d)+' in deep · '+across+' across</text>';document.getElementById('alcove-draw').innerHTML=s}'''
s = s[:draw_start] + new_draw + s[draw_end:]

sync_start = s.index('function syncAlcove()')
sync_end = s.index("\ndocument.addEventListener('click'", sync_start)
new_sync = '''function syncAlcove(){const n=+document.getElementById('c-n').value,d=+document.getElementById('c-d').value,w=+document.getElementById('c-w').value,sp=STORE_FIXTURE[alcove.material],selected=alcove.H.slice(0,n).slice().sort((a,b)=>a-b),maxShelf=selected[selected.length-1];let h=+document.getElementById('c-h').value;if(h<maxShelf){h=maxShelf;document.getElementById('c-h').value=h}const span=Math.max(0,w-1.5),gap=Math.max(0,45.5-w),across=Math.ceil(d/5.5),boardsPerShelf=Math.ceil(across/2),b96=boardsPerShelf*n,mat=+(b96*sp.unit96+4*sp.unit72).toFixed(2),rec=RECOVERY[across][n],cyc=CYCLE[across][n],hw=18,q=+(mat+rec+hw).toFixed(2),fit=gap<0.0001?'Full-width fit · no built-in gap allowance':fmt(gap)+' in total opening clearance';document.getElementById('v-h').textContent=fmt(h)+' in · room 94½';document.getElementById('v-w').textContent=fmt(w)+' in · opening 45½';document.getElementById('v-n').textContent=n+' shelves';document.getElementById('v-d').textContent=fmt(d)+' in · from 14½ measured';document.getElementById('p-h').textContent=fmt(h)+' in';document.getElementById('p-w').textContent=fmt(w)+' in';document.getElementById('p-d').textContent=fmt(d)+' in';document.getElementById('p-span').textContent=fmt(span)+' in';document.getElementById('p-fit').textContent=fit;document.getElementById('p-shelves').textContent=n;document.getElementById('p-heights').textContent=selected.map(fmt).join(', ')+' in';document.getElementById('p-material').textContent=sp.name;document.getElementById('p-cfg').textContent='Generated from room reference 94½ in → unit '+fmt(h)+' H × '+fmt(w)+' W × '+fmt(d)+' D · '+n+' shelves · '+sp.name;document.getElementById('p-mat').innerHTML=b96+' × 1×6×96 &nbsp;·&nbsp; 4 × 1×6×72<br><span class="dim">+ hardware pack</span>';document.getElementById('p-price').textContent=money(q);document.getElementById('p-basis').textContent='Reference budgetary estimate · material '+money(mat)+' + cell '+money(rec)+' + hardware '+money(hw);document.getElementById('o-sku').textContent=sp.sku.replace('STB-ZERO-','');document.getElementById('o-unit').textContent=money(sp.unit96);document.getElementById('o-oh').textContent=sp.onHand+' on hand';document.getElementById('o-span').textContent=fmt(span)+' in';document.getElementById('o-across').textContent=across;document.getElementById('o-b96').textContent=b96;document.getElementById('o-mat').textContent=money(mat);document.getElementById('o-hw').textContent=money(hw);document.getElementById('o-cyc').textContent=cyc+' min';document.getElementById('o-rec').textContent=money(rec);document.getElementById('r-uh').textContent=fmt(h)+' in';document.getElementById('r-uw').textContent=fmt(w)+' in';document.getElementById('r-span').textContent=fmt(span)+' in';document.getElementById('r-fit').textContent=gap<0.0001?'0 in — full-width fit':fmt(gap)+' in total clearance';document.getElementById('r-n').textContent=n;document.getElementById('r-d').textContent=fmt(d)+' in';document.getElementById('r-h').textContent=selected.map(fmt).join(', ')+' in';document.getElementById('r-sku').textContent=sp.name+' · '+sp.sku.replace('STB-ZERO-','');document.getElementById('r-q').textContent=money(q);document.querySelectorAll('[data-material]').forEach(x=>x.classList.toggle('on',x.dataset.material===alcove.material));drawAlcove(n,h,w,d,sp.color,across)}'''
s = s[:sync_start] + new_sync + s[sync_end:]

old_listeners = "document.getElementById('fmt').addEventListener('click',()=>{alcove.fraction=!alcove.fraction;document.getElementById('fmt').textContent=alcove.fraction?'fractions':'decimals';renderHeights();syncAlcove()});document.getElementById('shelves').addEventListener('change',e=>{const input=e.target.closest('[data-height-index]');if(!input)return;const i=+input.dataset.heightIndex,v=parseHeight(input.value);if(v!==null&&v>0&&v<94.5)alcove.H[i]=v;input.value=fmt(alcove.H[i]);syncAlcove()});document.getElementById('c-n').addEventListener('input',()=>{renderHeights();syncAlcove()});document.getElementById('c-d').addEventListener('input',syncAlcove);"
new_listeners = "document.getElementById('fmt').addEventListener('click',()=>{alcove.fraction=!alcove.fraction;document.getElementById('fmt').textContent=alcove.fraction?'fractions':'decimals';renderHeights();syncAlcove()});document.getElementById('shelves').addEventListener('change',e=>{const input=e.target.closest('[data-height-index]');if(!input)return;const i=+input.dataset.heightIndex,v=parseHeight(input.value),unitH=+document.getElementById('c-h').value;if(v!==null&&v>0&&v<=unitH)alcove.H[i]=v;input.value=fmt(alcove.H[i]);syncAlcove()});document.getElementById('c-n').addEventListener('input',()=>{renderHeights();syncAlcove()});document.getElementById('c-h').addEventListener('input',syncAlcove);document.getElementById('c-w').addEventListener('input',syncAlcove);document.getElementById('c-d').addEventListener('input',syncAlcove);"
once(old_listeners, new_listeners, 'alcove listeners')

old_tx = """function syncTransaction(){
 const n=+document.getElementById('c-n').value,d=+document.getElementById('c-d').value,sp=STORE_FIXTURE[alcove.material];
 const price=document.getElementById('p-price').textContent;
 document.getElementById('store-material').textContent=sp.name+' reference';
 document.getElementById('store-price').textContent=price;
 document.getElementById('review-price').textContent=price;
 document.getElementById('review-shelves').textContent=n;
 document.getElementById('request-summary').textContent=`Definition example · 45½″ opening · ${n} shelves · ${fmt(d)}″ deep · ${sp.name} · 44″ nominal span · back none`;
}"""
new_tx = """function syncTransaction(){
 const n=+document.getElementById('c-n').value,d=+document.getElementById('c-d').value,h=+document.getElementById('c-h').value,w=+document.getElementById('c-w').value,span=w-1.5,sp=STORE_FIXTURE[alcove.material];
 const price=document.getElementById('p-price').textContent;
 document.getElementById('store-material').textContent=sp.name+' reference';
 document.getElementById('store-price').textContent=price;
 document.getElementById('review-price').textContent=price;
 document.getElementById('review-shelves').textContent=n;
 document.getElementById('review-unit').textContent=fmt(h)+' H × '+fmt(w)+' W';
 document.getElementById('review-span').textContent=fmt(span)+' in nominal';
 document.getElementById('request-summary').textContent=`Definition example · ${fmt(h)}″ H × ${fmt(w)}″ W × ${fmt(d)}″ D · ${n} shelves · ${sp.name} · ${fmt(span)}″ nominal span · back none`;
}"""
once(old_tx, new_tx, 'transaction synchronization')

p.write_text(s)

assert s.count('<section class="page" id="alcove-config">') == 1
assert s.count('id="c-h"') == 1
assert s.count('id="c-w"') == 1
assert '72 in so the shelving fits the scale of the room' in s
assert 'rather trim a little drywall at installation' in s
assert 'RESULTING DEFINITION / REFERENCE ORDER — USER 1' in s
assert '<details class="how">' not in s
assert 'STORE / PRICE BASIS' in s
assert 'room 45½ W · 94½ H' in s
assert "drawAlcove(n,h,w,d,sp.color,across)" in s

ids = re.findall(r'\bid="([^"]+)"', s)
dupes = sorted({x for x in ids if ids.count(x) > 1})
if dupes:
    raise SystemExit('duplicate ids: ' + ', '.join(dupes))
